/** Production sampled-copy planner/scheduler against recording owner contracts.
 * These are not GPU execution or full renderer integration tests. In particular,
 * an authored chain is borrowed from the existing target owner, not allocated,
 * uploaded or regenerated by this module.
 */
import test from 'node:test';
import assert from 'node:assert/strict';
import {copySampledTexture} from './three_sampled_texture_copy.mjs';

const error = code => Object.assign(new Error(code), {code});
const point = (x, y, z) => ({isVector3: true, x, y, z});
const box = (x, y, z, width, height, depth) => ({isBox3: true,
  min: {x, y, z}, max: {x: x + width, y: y + height, z: z + depth}});
function deferred() {
  let resolve, reject;
  const promise = new Promise((yes, no) => { resolve = yes; reject = no; });
  promise.catch(() => {});
  return {promise, resolve, reject};
}
function fixture(options = {}) {
  const events = [], commands = [], errors = [], active = new Set(), history = new Map(), validations = [];
  let refs = 0, releases = 0, rollbacks = 0, sourceReleases = 0;
  const source = {version: 1, alive: true, bytes: Uint8Array.of(1, 2, 3, 4),
    shape: {width: 2, height: 2, depth: 1, mipLevelCount: 1, format: 'rgba8unorm', viewDimension: '2d'}};
  const destination = {isTexture: true, isRenderTargetTexture: true, generateMipmaps: false};
  const target = {alive: true, epoch: 1, textures: [destination]};
  destination.renderTarget = target;
  const shape = {width: 8, height: 8, layers: 1, mipLevelCount: 4,
    format: 'rgba8unorm', viewDimension: '2d', generateMipmaps: false,
    sampleCount: 1, cube: false, depthFormat: null, depthLayers: 1, depthArray: false, ...options};
  const nativeDestination = {target};
  const device = {
    limits: {maxTextureDimension2D: 8192, maxTextureDimension3D: 2048, maxTextureArrayLayers: 256},
    createCommandEncoder() {
      events.push('encode'); let copy;
      return {copyTextureToTexture(from, to, size) { copy = {from, to, size}; },
        finish() { device.onFinish?.(); return copy; }};
    },
    queue: {submit(batch) {
      device.onSubmit?.(); events.push('submit');
      commands.push(...batch.map(copy => ({...copy, bytes: [...copy.from.texture.bytes]})));
    }},
  };
  const targets = {
    getTextureTarget(value) { return value.renderTarget === target ? target : null; },
    capture(value) {
      assert.equal(value, target);
      return {target, epoch: target.epoch,
        shape: {...shape, textures: target.textures.slice(), colors: target.textures.map(() => ({...shape}))}};
    },
    assertCurrent(entry) {
      if (!target.alive || entry.epoch !== target.epoch || entry.shape.textures.some((t, i) => t !== target.textures[i]))
        throw error('STALE_TARGET');
    },
    retainGeneration(entry) {
      targets.assertCurrent(entry); refs++; let live = true;
      return () => { assert.ok(live, 'release target generation only once'); live = false; refs--; releases++; };
    },
    validateNativeTextures(borrows) {
      events.push('preflight');
      for (const borrow of borrows) {
        targets.assertCurrent(borrow.entry);
        assert.equal(borrow.device, device); assert.equal(borrow.depth, false);
        assert.equal(borrow.texture, target.textures[borrow.colorIndex]);
      }
      if (targets.budgetError) throw targets.budgetError;
    },
    withNativeColorDestination(borrow, run, {validation}) {
      targets.assertCurrent(borrow.entry); events.push('destination');
      const result = run(nativeDestination);
      const task = Promise.resolve(validation); task.catch(() => {}); validations.push(task);
      return result;
    },
  };
  const inputs = {
    captureDispatch(run) {
      const before = new Map(history);
      try { return run(); }
      catch (e) { rollbacks++; history.clear(); for (const [k, v] of before) history.set(k, v); throw e; }
    },
    captureBinding({texture}) {
      events.push('capture'); assert.equal(texture, source);
      let record = history.get(texture);
      if (!record || record.version !== texture.version) {
        record = {version: texture.version, bytes: texture.bytes.slice(), shape: {...texture.shape}};
        history.set(texture, record);
      }
      const lease = {record}; active.add(lease); return lease;
    },
    copyShape(lease) { return lease.record.shape; },
    preparation() { return source.ready ?? null; },
    validateDispatch(leases) {
      for (const lease of leases) if (!active.has(lease) || !source.alive) throw error('STALE_SOURCE');
    },
    withTexture(lease, run) {
      inputs.validateDispatch([lease]); events.push('upload'); source.onUpdate?.();
      inputs.validateDispatch([lease]); return run(lease.record);
    },
    whenIdle() { return Promise.all([...validations, source.validation]); },
    release(lease) { assert.ok(active.delete(lease), 'release sampled source only once'); sourceReleases++; },
  };
  const renderer = {_device: device, _targets: targets, _targetLifetime: new AbortController(),
    _getSampledTextureInputs: () => inputs, _pending: [], _preparing: false,
    _enqueue(request) { if (renderer.queueError) throw renderer.queueError; renderer._pending.push(request); }};
  const copy = (region = null, position = null, sourceLevel = 0, destinationLevel = 2) =>
    copySampledTexture(renderer, source, destination, region, position, sourceLevel, destinationLevel, e => errors.push(e));
  async function flush() {
    while (renderer._pending.length) {
      const request = renderer._pending.shift();
      try { const result = request.issue(); request.resolve(request.awaitSubmission ? await result : result); }
      catch (e) { request.reject(e); }
    }
  }
  const dispose = () => {
    renderer._disposed = true; renderer._targetLifetime.abort(error('DISPOSED'));
    for (const request of renderer._pending.splice(0)) request.reject(error('DISPOSED'));
  };
  return {source, destination, target, shape, device, renderer, targets, inputs, nativeDestination,
    events, commands, errors, history, active, validations, copy, flush, dispose,
    get refs() { return refs; }, get releases() { return releases; },
    get sourceReleases() { return sourceReleases; }, get rollbacks() { return rollbacks; }};
}
const released = f => {
  assert.equal(f.refs, 0); assert.equal(f.active.size, 0);
  assert.equal(f.releases, 1); assert.equal(f.sourceReleases, 1);
};

for (const dimension of ['2d', '2d-array', '3d']) {
  test(`copies into an authored ${dimension} target mip using the native allocation`, async () => {
    const f = fixture({viewDimension: dimension, layers: dimension === '2d' ? 1 : 8});
    const z = dimension === '2d' ? 0 : dimension === '3d' ? 1 : 7;
    assert.equal(f.copy(null, point(0, 0, z)), undefined);
    assert.equal(f.commands.length, 1);
    assert.equal(f.commands[0].to.texture, f.nativeDestination);
    assert.equal(f.commands[0].to.mipLevel, 2);
    assert.deepEqual(f.commands[0].to.origin, [0, 0, z]);
    assert.deepEqual(f.commands[0].size, [2, 2, 1]);
    assert.deepEqual(f.commands[0].bytes, [1, 2, 3, 4]);
    assert.ok(f.events.indexOf('preflight') < f.events.indexOf('upload'));
    released(f); await Promise.all(f.validations);
  });
}

test('independent source/destination mips and non-power-of-two extents use mip-local coordinates', () => {
  const f = fixture({width: 15, height: 9});
  f.source.shape = {...f.source.shape, width: 10, height: 6, mipLevelCount: 4};
  f.copy(box(1, 0, 0, 2, 2, 1), point(1, 0, 0), 1, 2);
  assert.equal(f.commands[0].from.mipLevel, 1);
  assert.deepEqual(f.commands[0].from.origin, [1, 0, 0]);
  assert.deepEqual(f.commands[0].to.origin, [1, 0, 0]);
  assert.deepEqual(f.commands[0].size, [2, 2, 1]); released(f);
});

test('volume mip depth shrinks, but array layer count does not', () => {
  const volume = fixture({viewDimension: '3d', layers: 8});
  assert.throws(() => volume.copy(null, point(0, 0, 2)), {code: 'THREE_STORAGE_COPY_BOUNDS'});
  assert.equal(volume.commands.length, 0); assert.equal(volume.history.size, 0); released(volume);
  const array = fixture({viewDimension: '2d-array', layers: 8});
  array.copy(null, point(0, 0, 7)); assert.equal(array.commands[0].to.origin[2], 7); released(array);
});

test('authored cube mip copies address face ranges without shrinking the six layers', () => {
  const f = fixture({cube: true, viewDimension: 'cube', layers: 6});
  f.source.shape = {...f.source.shape, viewDimension: '2d-array', depth: 3};
  f.copy(box(0, 0, 1, 2, 2, 2), point(0, 0, 4));
  assert.deepEqual(f.commands[0].from.origin, [0, 0, 1]);
  assert.deepEqual(f.commands[0].to.origin, [0, 0, 4]);
  assert.deepEqual(f.commands[0].size, [2, 2, 2]); released(f);
});

test('cube face bounds and full allocation layer limits reject before source upload', () => {
  for (const limit of [false, true]) {
    const f = fixture({cube: true, viewDimension: 'cube', layers: 6});
    if (limit) f.device.limits.maxTextureArrayLayers = 5;
    assert.throws(() => f.copy(null, point(0, 0, limit ? 0 : 6)),
      {code: 'THREE_STORAGE_COPY_' + (limit ? 'LIMIT' : 'BOUNDS')});
    assert.ok(!f.events.includes('upload')); assert.equal(f.commands.length, 0); released(f);
  }
});

test('cube policy follows the current public flag and remains captured through the FIFO', async () => {
  const f = fixture({cube: true, viewDimension: 'cube', layers: 6, generateMipmaps: true});
  f.renderer._preparing = true;
  f.copy(null, point(0, 0, 5)); // Public false overrides the earlier descriptor's true.
  f.destination.generateMipmaps = true;
  for (const level of [0, 2])
    assert.throws(() => f.copy(null, null, 0, level), {code: 'THREE_STORAGE_COPY_LEVEL'});
  await f.flush(); assert.equal(f.commands.length, 1); assert.deepEqual(f.errors, []); released(f);
});

test('multi-slice source copies select an authored volume mip without changing source pixels', () => {
  const f = fixture({viewDimension: '3d', layers: 16});
  f.source.shape = {...f.source.shape, viewDimension: '2d-array', depth: 6};
  const before = f.source.bytes.slice();
  f.copy(box(0, 0, 2, 2, 2, 2), point(0, 0, 1));
  assert.deepEqual(f.commands[0].from.origin, [0, 0, 2]);
  assert.deepEqual(f.commands[0].size, [2, 2, 2]); assert.deepEqual(f.source.bytes, before); released(f);
});

test('higher automatically generated mips stay rejected without borrowing or uploading', () => {
  for (const generateMipmaps of [true, undefined]) {
    const f = fixture({generateMipmaps});
    assert.throws(() => f.copy(), {code: 'THREE_STORAGE_COPY_LEVEL'});
    assert.deepEqual(f.events, []); assert.equal(f.refs, 0); assert.equal(f.history.size, 0);
  }
});

test('level-zero automatic-mipmap targets retain their existing raw destination path', () => {
  const f = fixture({generateMipmaps: true}); f.copy(null, null, 0, 0);
  assert.equal(f.commands[0].to.mipLevel, 0); released(f);
});

test('unallocated and invalid destination levels fail without source uploads', () => {
  for (const level of [-1, 4, 1.5, NaN, Infinity]) {
    const f = fixture(); assert.throws(() => f.copy(null, null, 0, level), {code: 'THREE_STORAGE_COPY_LEVEL'});
    assert.ok(!f.events.includes('upload')); assert.equal(f.commands.length, 0);
    assert.equal(f.history.size, 0); released(f);
  }
});

test('queued mip writes freeze source versions, origins and the selected level', async () => {
  const f = fixture(); f.renderer._preparing = true;
  const region = box(0, 0, 0, 1, 1, 1), position = point(1, 1, 0);
  f.copy(region, position); f.source.version++; f.source.bytes.fill(9); f.copy(region, position);
  f.source.bytes.fill(77); region.min.x = 99; position.x = 99;
  assert.equal(f.refs, 2); await f.flush();
  assert.deepEqual(f.commands.map(c => c.bytes), [[1, 2, 3, 4], [9, 9, 9, 9]]);
  assert.ok(f.commands.every(c => c.to.mipLevel === 2 && c.to.origin.join() === '1,1,0'));
  assert.equal(f.releases, 2); assert.equal(f.sourceReleases, 2); assert.equal(f.refs, 0);
  assert.deepEqual(f.errors, []);
});

test('resizing or replacing an attachment rejects a queued mip write before upload', async () => {
  for (const change of [f => f.target.epoch++, f => { f.target.textures[0] = {}; }]) {
    const f = fixture(); f.renderer._preparing = true; f.copy(); change(f); await f.flush();
    assert.equal(f.errors[0].code, 'STALE_TARGET'); assert.ok(!f.events.includes('upload'));
    assert.equal(f.commands.length, 0); released(f);
  }
});

test('empty mip regions and full queues roll back captured history and generations', () => {
  const empty = fixture(); empty.copy(box(0, 0, 0, 0, 1, 1));
  assert.equal(empty.history.size, 0); assert.equal(empty.commands.length, 0); released(empty);
  const full = fixture(); full.renderer._preparing = true; full.renderer.queueError = error('FULL');
  assert.throws(() => full.copy(), {code: 'FULL'});
  assert.equal(full.history.size, 0); assert.equal(full.commands.length, 0); released(full);
});

test('private image readiness preserves FIFO ordering for authored mip writes', async () => {
  const f = fixture(), ready = deferred(); f.source.ready = ready.promise; f.copy();
  f.renderer._pending.push({issue() { f.events.push('later'); }, resolve() {}, reject: assert.fail});
  const drain = f.flush(); await Promise.resolve();
  assert.equal(f.commands.length, 0); assert.ok(!f.events.includes('later'));
  ready.resolve(); await drain;
  assert.ok(f.events.indexOf('submit') < f.events.indexOf('later')); released(f);
});

test('disposal releases a waiting mip copy; late image readiness cannot submit it', async () => {
  const f = fixture(), ready = deferred(); f.source.ready = ready.promise; f.copy();
  const drain = f.flush(); await Promise.resolve(); f.dispose(); await drain;
  ready.resolve(); await Promise.resolve(); await Promise.resolve();
  assert.equal(f.commands.length, 0); assert.equal(f.errors.length, 1); released(f);
});

test('source GPU validation reaches target completion without creating a cycle', async () => {
  const f = fixture(); f.source.validation = Promise.reject(error('SOURCE_GPU'));
  f.source.validation.catch(() => {}); f.copy();
  await assert.rejects(Promise.all(f.validations), {code: 'SOURCE_GPU'}); released(f);
});

test('encoding failures release an authored destination on immediate and deferred paths', async () => {
  for (const queued of [false, true]) {
    const f = fixture(); f.renderer._preparing = queued;
    f.device.onFinish = () => { throw error('ENCODE'); };
    if (queued) { f.copy(); await f.flush(); assert.equal(f.errors[0].code, 'ENCODE'); }
    else assert.throws(() => f.copy(), {code: 'ENCODE'});
    assert.equal(f.commands.length, 0); released(f);
  }
});

test('array layer limits reject before source uploads, even for small selected mip regions', () => {
  const f = fixture({viewDimension: '2d-array', layers: 257});
  assert.throws(() => f.copy(null, null, 0, 0), {code: 'THREE_STORAGE_COPY_LIMIT'});
  assert.ok(!f.events.includes('upload')); assert.equal(f.commands.length, 0); released(f);
});

test('volume color and independent array depth use separate device layer limits', () => {
  const f = fixture({viewDimension: '3d', layers: 512, depthArray: true, depthLayers: 512, depthFormat: 'depth32float'});
  assert.throws(() => f.copy(null, null, 0, 0), {code: 'THREE_STORAGE_COPY_LIMIT'});
  assert.ok(!f.events.includes('upload')); assert.equal(f.commands.length, 0); released(f);
  const colorOnly = fixture({viewDimension: '3d', layers: 512}); colorOnly.copy();
  assert.equal(colorOnly.commands.length, 1); released(colorOnly);
});

test('volume color with 2D depth preflights both dimension limits before upload', () => {
  const f = fixture({viewDimension: '3d', width: 16, height: 16, layers: 16, depthFormat: 'depth24plus'});
  f.device.limits.maxTextureDimension2D = 8;
  assert.throws(() => f.copy(null, null, 0, 0), {code: 'THREE_STORAGE_COPY_LIMIT'});
  assert.ok(!f.events.includes('upload')); released(f);
});

test('whole allocation limits, not selected mip dimensions, determine admission', () => {
  const f = fixture({viewDimension: '3d', width: 32, height: 32, layers: 32, mipLevelCount: 6});
  f.device.limits.maxTextureDimension3D = 16;
  assert.throws(() => f.copy(), {code: 'THREE_STORAGE_COPY_LIMIT'});
  assert.ok(!f.events.includes('upload')); released(f);
});

test('missing array-layer device limits fail before upload; exact limits remain valid', () => {
  const missing = fixture({viewDimension: '2d-array', layers: 1});
  delete missing.device.limits.maxTextureArrayLayers;
  assert.throws(() => missing.copy(null, null, 0, 0), {code: 'THREE_STORAGE_COPY_LIMIT'});
  assert.ok(!missing.events.includes('upload')); released(missing);
  const exact = fixture({viewDimension: '2d-array', layers: 256});
  exact.copy(null, point(0, 0, 255)); assert.equal(exact.commands[0].to.origin[2], 255); released(exact);
});

test('multisample destination boundaries remain explicit', () => {
  const f = fixture({sampleCount: 4});
  assert.throws(() => f.copy(), {code: 'THREE_STORAGE_COPY_SAMPLES'});
  assert.equal(f.commands.length, 0); assert.equal(f.refs, 0); assert.equal(f.history.size, 0);
});
